INSERT INTO `bs_announce` VALUES ('2c9267606f8ee551016f8f0062bf0001','zhaoziyu','2020-01-10 18:29:24','zhaoziyu','2020-01-10 19:28:21','files/20200110062922221_.svg,files/20200110064025766_项目开发计划书.pdf','4','9e45b49643a44c92b281d61244a3d554','行政公告',NULL,'[泸州公司]泸州公司1月9日职业化办公检查通报',NULL,NULL),('2c9267606f9cace4016f9d0774b10005','zhaoziyu','2020-01-13 11:51:49','zhaoziyu','2020-01-13 11:52:39','files/20200113115137767_OA系统上线新功能通知一.pdf,files/20200113115146123_OA系统上线新功能通知二.pdf','4','83e75e48228942d2bdcb45f391eb84cc','行政公告',NULL,'[现代服务业集团]关于OA系统上线应收款核销固化流程的通知',NULL,NULL),('2c92676070665b4201708ad77a120018','zhaoziyu','2020-02-28 16:09:02',NULL,NULL,'files/20200228040901549_蓝光生态人力号关于蓝光生态集团财务及预算管理中心詹子宇醉酒驾车的处罚通报.pdf','4','83e75e48228942d2bdcb45f391eb84cc','行政公告',NULL,'   [蓝光生态集团]蓝光生态人力（2020）02-28号关于蓝光生态集团财务及预算管理中心詹子宇醉酒驾车的处罚通报',NULL,'<p><span style=\"font-family: &aring;&frac34;&reg;&egrave;&frac12;&macr;&eacute;&rsaquo;&hellip;&eacute;&raquo;&lsquo;, &aring;&reg;&lsaquo;&auml;&frac12;&ldquo;, Arial, sans-serif; font-size: 12px; background-color: #ffffff;\">&nbsp;</span><span class=\"titleSpan\" style=\"margin: 4px 0px 0px; padding: 0px; font-size: 16px; font-family: &aring;&frac34;&reg;&egrave;&frac12;&macr;&eacute;&rsaquo;&hellip;&eacute;&raquo;&lsquo;, &aring;&reg;&lsaquo;&auml;&frac12;&ldquo;, Arial, sans-serif; cursor: pointer; background-color: #ffffff;\">[蓝光生态集团]蓝光生态人力（2020）02-28号关于蓝光生态集团财务及预算管理中心詹子宇醉酒驾车的处罚通报</span></p>'),('2c92676070665b420170c7bf17380060','zhaoziyu','2020-03-11 11:59:14','zhaoziyu','2020-03-11 11:59:47','files/20200311115900501_蓝光集团年第一季度PBC绩效考核.pdf','4','83e75e48228942d2bdcb45f391eb84cc','行政公告',NULL,'[蓝光发展]关于2020年第一季度度个人绩效PBC考核工作安排的通知',NULL,'<h1 style=\"text-align: center;\"><span style=\"font-family: 微软雅黑, 宋体, Arial, sans-serif; font-size: 12px; background-color: #ffffff;\">&nbsp; </span><span class=\"titleSpan\" style=\"margin: 4px 0px 0px; padding: 0px; font-size: 16px; font-family: 微软雅黑, 宋体, Arial, sans-serif; cursor: pointer; background-color: #ffffff;\">关于2020年第一季度度个人绩效PBC考核工作安排的通知</span></h1>\n<p><span class=\"titleSpan\" style=\"margin: 4px 0px 0px; padding: 0px; font-size: 16px; font-family: 微软雅黑, 宋体, Arial, sans-serif; cursor: pointer; background-color: #ffffff;\">各中心、各业务单位：</span></p>\n<p>&nbsp;</p>\n<p><span class=\"titleSpan\" style=\"margin: 4px 0px 0px; padding: 0px; font-size: 16px; font-family: 微软雅黑, 宋体, Arial, sans-serif; cursor: pointer; background-color: #ffffff;\">现就一季度个人绩效PBC考核相关工作安排如下，请各单位参考节点组织落实，各单位可根据自身实际情况安排具体计划，节点完成日期不得晚于下表要求。内容如下：</span></p>\n<p>&nbsp;</p>\n<p><span class=\"titleSpan\" style=\"margin: 4px 0px 0px; padding: 0px; font-size: 16px; font-family: 微软雅黑, 宋体, Arial, sans-serif; cursor: pointer; background-color: #ffffff;\">最晚完成日期</span></p>\n<p>&nbsp;</p>\n<p><span class=\"titleSpan\" style=\"margin: 4px 0px 0px; padding: 0px; font-size: 16px; font-family: 微软雅黑, 宋体, Arial, sans-serif; cursor: pointer; background-color: #ffffff;\">员工完成个人PBC表单评分人、权重、目标设置 </span><span class=\"titleSpan\" style=\"margin: 4px 0px 0px; padding: 0px; font-size: 16px; font-family: 微软雅黑, 宋体, Arial, sans-serif; cursor: pointer; background-color: #ffffff;\">3月15日</span></p>\n<p><span class=\"titleSpan\" style=\"margin: 4px 0px 0px; padding: 0px; font-size: 16px; font-family: 微软雅黑, 宋体, Arial, sans-serif; cursor: pointer; background-color: #ffffff;\">上级完成PBC表审核确认&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;3月18日</span></p>\n<p><span class=\"titleSpan\" style=\"margin: 4px 0px 0px; padding: 0px; font-size: 16px; font-family: 微软雅黑, 宋体, Arial, sans-serif; cursor: pointer; background-color: #ffffff;\">完成一季度PBC员工自评、上级评分&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</span><span class=\"titleSpan\" style=\"margin: 4px 0px 0px; padding: 0px; font-size: 16px; font-family: 微软雅黑, 宋体, Arial, sans-serif; cursor: pointer; background-color: #ffffff;\">4月06日</span></p>\n<p><span class=\"titleSpan\" style=\"margin: 4px 0px 0px; padding: 0px; font-size: 16px; font-family: 微软雅黑, 宋体, Arial, sans-serif; cursor: pointer; background-color: #ffffff;\">确认一季度参与考核排名人员名单&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;4月06日</span></p>\n<p><span class=\"titleSpan\" style=\"margin: 4px 0px 0px; padding: 0px; font-size: 16px; font-family: 微软雅黑, 宋体, Arial, sans-serif; cursor: pointer; background-color: #ffffff;\">完成一季度PBC考核结果强排&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 4月10日</span></p>\n<p><span class=\"titleSpan\" style=\"margin: 4px 0px 0px; padding: 0px; font-size: 16px; font-family: 微软雅黑, 宋体, Arial, sans-serif; cursor: pointer; background-color: #ffffff;\">完成个人绩效PRR沟通&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;4月15日</span></p>\n<p>&nbsp;</p>\n<p><span class=\"titleSpan\" style=\"margin: 4px 0px 0px; padding: 0px; font-size: 16px; font-family: 微软雅黑, 宋体, Arial, sans-serif; cursor: pointer; background-color: #ffffff;\">1、请各单位人力资源相关人员在执行过程中关注如下重点环节，发现问题及时与总部沟通。</span></p>\n<p><span class=\"titleSpan\" style=\"margin: 4px 0px 0px; padding: 0px; font-size: 16px; font-family: 微软雅黑, 宋体, Arial, sans-serif; cursor: pointer; background-color: #ffffff;\">（1）所有员工须参照《各类员工绩效考核操作标准》严格执行。</span></p>\n<p><span class=\"titleSpan\" style=\"margin: 4px 0px 0px; padding: 0px; font-size: 16px; font-family: 微软雅黑, 宋体, Arial, sans-serif; cursor: pointer; background-color: #ffffff;\">（2）认真检查考核期内新聘、离职、病产孕、强管控管理体系人员、调动借调人员是否参与考核和排名、考核人和参与排名的单位是否正确，重点关注异动人员并与异动涉及单位人力资源部门沟通，防止错漏。</span></p>\n<p><span class=\"titleSpan\" style=\"margin: 4px 0px 0px; padding: 0px; font-size: 16px; font-family: 微软雅黑, 宋体, Arial, sans-serif; cursor: pointer; background-color: #ffffff;\">（3）强管控体系区域人员由总部职能部门统一排名，包括：审计、法务、财务、招采职能相关人员。请总部职能部门加强与区域的沟通，重点确认纳入总部绩效排名的人员名单，防止错漏。</span></p>\n<p><span class=\"titleSpan\" style=\"margin: 4px 0px 0px; padding: 0px; font-size: 16px; font-family: 微软雅黑, 宋体, Arial, sans-serif; cursor: pointer; background-color: #ffffff;\">（4）组织变革PBC考核评分人与权重调整相关岗位需按方案调整执行，区域人力组织自行检查，总部进行专项抽查，不合规项目按《2020年人力资源体系积分管理方案》予以扣分，1分/项。</span></p>\n<p>&nbsp;</p>\n<p><span class=\"titleSpan\" style=\"margin: 4px 0px 0px; padding: 0px; font-size: 16px; font-family: 微软雅黑, 宋体, Arial, sans-serif; cursor: pointer; background-color: #ffffff;\">2、请蓝光生命科技集团、现代服务业集团根据自身制度规定开展2020年一季度个人绩效考核。</span></p>\n<p>&nbsp;</p>\n<p><span class=\"titleSpan\" style=\"margin: 4px 0px 0px; padding: 0px; font-size: 16px; font-family: 微软雅黑, 宋体, Arial, sans-serif; cursor: pointer; background-color: #ffffff;\">特此通知！</span></p>\n<p>&nbsp;</p>'),('2c92676070665b420170c959e32d0063','zhaoziyu','2020-03-11 19:27:56',NULL,NULL,'files/20200311072755311_课件PPT技能培训上手篇进阶篇压缩只读.pptx','4','4f13c13373b1465aa1c4e12563bdadcf','行政公告',NULL,'PPT技巧培训',NULL,'<p>PPT技巧培训</p>'),('2c92676070665b420170c9a7df9a0064','admin','2020-03-11 20:53:07',NULL,NULL,'files/20200311085304486_神经网络与深度学习复旦教授入门介绍.pptx,files/20200311085253442_神经网络与深度学习.pdf','4','83e75e48228942d2bdcb45f391eb84cc','行政公告',NULL,'人工智能与深度学习',NULL,'<p>人工智能与深度学习</p>');
/*!40000 ALTER TABLE `bs_announce` ENABLE KEYS */;
UNLOCK TABLES;

