DROP TABLE IF EXISTS `bs_attendance_details`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `bs_attendance_details` (
  `id` varchar(36) NOT NULL COMMENT '主键',
  `no` varchar(32) DEFAULT NULL COMMENT '序号',
  `adate` varchar(32) DEFAULT NULL COMMENT '考勤异常时间',
  `type` varchar(32) DEFAULT NULL COMMENT '异常类别',
  `content` varchar(100) DEFAULT NULL COMMENT '异常原因',
  `foreign_key_id` varchar(32) DEFAULT NULL COMMENT '外键',
  `create_by` varchar(100) DEFAULT NULL COMMENT '创建人',
  `create_time` varchar(32) DEFAULT NULL COMMENT '创建时间',
  `work_info_on` varchar(32) DEFAULT NULL COMMENT '上班考勤',
  `work_info_off` varchar(32) DEFAULT NULL COMMENT '下班考勤',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

