--
-- Table structure for table `bs_blog`
--

DROP TABLE IF EXISTS `bs_blog`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `bs_blog` (
  `id` varchar(36) COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键',
  `create_by` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建日期',
  `update_by` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新日期',
  `blog_title` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '博文标题',
  `content` text COLLATE utf8mb4_general_ci COMMENT '博文内容',
  `page_tags` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '博文标签',
  `page_column` varchar(100) COLLATE utf8mb4_general_ci DEFAULT '社会聚焦' COMMENT '博文分类',
  `page_type` varchar(32) COLLATE utf8mb4_general_ci DEFAULT 'Y' COMMENT '博文类型',
  `page_scope` int(32) DEFAULT '1' COMMENT '发布形式',
  `hontent` text COLLATE utf8mb4_general_ci COMMENT '网页内容',
  `bpm_status` varchar(32) COLLATE utf8mb4_general_ci DEFAULT '1' COMMENT '审核状态',
  `flag` varchar(32) COLLATE utf8mb4_general_ci DEFAULT 'N' COMMENT '草稿标识',
  `star` int(32) DEFAULT NULL COMMENT '收藏数目',
  `messages` int(32) DEFAULT NULL COMMENT '消息数目',
  `likes` int(32) DEFAULT NULL COMMENT '喜欢数目',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

