DROP TABLE IF EXISTS `bs_egress`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `bs_egress` (
  `id` varchar(36) NOT NULL COMMENT '主键',
  `create_by` varchar(50) DEFAULT NULL COMMENT '申请人员',
  `create_time` datetime DEFAULT NULL COMMENT '创建日期',
  `update_by` varchar(50) DEFAULT NULL COMMENT '更新人员',
  `update_time` datetime DEFAULT NULL COMMENT '更新日期',
  `sys_org_code` varchar(64) DEFAULT NULL COMMENT '所属部门',
  `proposer` varchar(100) DEFAULT NULL COMMENT '申请人员',
  `starttime` varchar(32) DEFAULT NULL COMMENT '开始时间',
  `endtime` varchar(32) DEFAULT NULL COMMENT '结束时间',
  `location` varchar(1000) DEFAULT NULL COMMENT '外出地点',
  `people` varchar(1000) DEFAULT NULL COMMENT '随行人员',
  `bpm_status` varchar(32) DEFAULT '1' COMMENT '流程状态',
  `files` varchar(1000) DEFAULT NULL COMMENT '附件',
  `content` varchar(1000) DEFAULT NULL COMMENT '外出原因',
  `depart_name` varchar(100) DEFAULT NULL COMMENT '所属部门',
  `total_days` varchar(32) DEFAULT NULL COMMENT '合计天数',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

