DROP TABLE IF EXISTS `bs_short_link`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `bs_short_link` (
  `id` varchar(36) COLLATE utf8mb4_general_ci NOT NULL,
  `code` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '编码',
  `url` varchar(1000) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '地址',
  `count` int(11) DEFAULT NULL COMMENT '剩余次数',
  `expire` datetime DEFAULT NULL COMMENT '到期时间',
  `time` datetime DEFAULT NULL COMMENT '时间戳',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

