--
-- Table structure for table `bs_travel`
--

DROP TABLE IF EXISTS `bs_travel`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `bs_travel` (
  `id` varchar(36) NOT NULL COMMENT '主键',
  `create_by` varchar(50) DEFAULT NULL COMMENT '申请人员',
  `create_time` datetime DEFAULT NULL COMMENT '填表时间',
  `update_by` varchar(50) DEFAULT NULL COMMENT '更新人员',
  `update_time` datetime DEFAULT NULL COMMENT '更新日期',
  `sys_org_code` varchar(1000) DEFAULT NULL COMMENT '所属部门',
  `starttime` varchar(32) DEFAULT NULL COMMENT '开始日期',
  `endtime` varchar(32) DEFAULT NULL COMMENT '结束日期',
  `total_days` varchar(32) DEFAULT '1.00' COMMENT '合计天数',
  `content` varchar(4000) DEFAULT NULL COMMENT '出差事由',
  `entourage` varchar(1000) DEFAULT NULL COMMENT '随行人员',
  `predict_fee` varchar(1000) DEFAULT '￥1000.00' COMMENT '费用预估',
  `drive_type` varchar(1000) DEFAULT '否' COMMENT '是否自驾',
  `predict_mileage` varchar(1000) DEFAULT '1000' COMMENT '预估里程',
  `bpm_status` varchar(1000) DEFAULT '1' COMMENT '流程状态',
  `no` varchar(100) DEFAULT NULL COMMENT '表单编号',
  `depart_name` varchar(64) DEFAULT NULL COMMENT '所属部门',
  `employee_rank` varchar(100) DEFAULT NULL COMMENT '员工职级',
  `travel_remarks` varchar(1000) DEFAULT NULL COMMENT '备注说明',
  `travel_transport` varchar(1000) DEFAULT '飞机' COMMENT '乘坐交通工具',
  `travel_address` varchar(1000) DEFAULT NULL COMMENT '出差地点',
  `files` varchar(1000) DEFAULT NULL COMMENT '附件',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `bs_travel`
--

LOCK TABLES `bs_travel` WRITE;
/*!40000 ALTER TABLE `bs_travel` DISABLE KEYS */;
INSERT INTO `bs_travel` VALUES ('2c9267606f7eaeb6016f7eb224b80001','陈宝庆','2020-01-07 14:30:01','chenbaoqing','2020-02-05 15:55:02','A04A17','2020-01-07 08:28:33','2020-01-18 14:28:37','12','<h1>根据公司领导指示，协助云南（玉溪、楚雄等地）项目前期工作</h1>\n<p>1、协助邬存之总 易门美丽县城项目；</p>\n<p>2、协助楚雄州城投 光禄小镇项目；</p>\n<p>3、协助玉溪市交通运输局 2020年重点项目投融资交流；</p>\n<p>4、云南其他项目拓展</p>','','￥13000','否','2200公里','5',NULL,'2703b6aa8fc344299f86a213e3262966','P4',NULL,'飞机,动车或高铁','云南 昆明 玉溪 楚雄等地市',''),('2c9267606f7fb228016f88c171f70004','王大江','2020-01-09 13:22:56',NULL,NULL,'A04A17','2020-01-10 13:20:12','2020-01-11 13:20:19','2','<p>常州项目现场管理跟踪，梳理计划。</p>',NULL,'900','是','150公里','1',NULL,'8a4b2fea8a6348e39659dfa0cf5ed14b','M4',NULL,'其他','常州',''),('2c9267606f7fb228016f8960bc090008','常青	','2020-01-09 16:16:55','changqing','2020-01-09 16:33:14','A04A17','2020-01-14 05:00:00','2020-01-16 08:09:10','3','<p>如约拜访复地集团，北京城市公司总经理，及招采部负责人，进行节前商务拜访及沟通，了解通州X05地块项目具体发标时间。</p>',NULL,'￥2500.00','是','1800KM','10',NULL,'a5d90cd4c02e4f3789b355b0006ed321','P4',NULL,'动车或高铁','北京','files/20200109043313057_差旅费依据.xlsx'),('2c9267606f8d601d016f8d601d070000','王自强','2020-01-10 10:54:43','wangziqiang','2020-01-10 15:39:27','A04A17','2020-01-12 06:43:41','2020-01-14 20:01:48','3.00','<p>到射阳鹤乡项目了解情况，协助处理项目备案事宜。返程后到青白江区与区公安局、应急管理局、消防大队领导碰面。</p>',NULL,'￥4000.00','否','','5',NULL,'2703b6aa8fc344299f86a213e3262966','P6','因提前与青白江区公安局、应急管理局、消防大队领导约定1月14日下午碰面，盐城南洋机场仅一班返程航班，如1月14日从此机场返程回成都已是19：55。特申请到南京中转乘机提前返回成都，按时赶至青白江与区领导碰面。','飞机','成都——射阳鹤乡项目——南京（中转）——青白江',''),('2c9267606f8d601d016f8e6082810002','马利国','2020-01-10 15:34:47',NULL,NULL,'A04A17','2020-01-13 15:33:31','2020-01-15 15:33:40','3','<p>回集团述职</p>',NULL,'3500','否','1000','4',NULL,'2703b6aa8fc344299f86a213e3262966','P4',NULL,'飞机','沈阳-成都-沈阳',''),('2c9267606f8f09e6016f8f09e6220000','张义鹏','2020-01-10 18:39:48','zhangyipeng','2020-01-14 12:01:39','A04A17','2020-01-13 18:36:15','2020-01-16 18:36:21','4','<p>根据公司通知要求，参加公司14号的述职会议。特申请13号从济南出发，14号参加会议，16号回到济南，共3天。</p>',NULL,'3000','否','3500公里','4',NULL,'2703b6aa8fc344299f86a213e3262966','P4',NULL,'动车或高铁','成都、济南',''),('2c9267606f9cace4016f9cdc974b0003','范斌','2020-01-13 11:04:59',NULL,NULL,'A04A17','2020-01-17 10:53:34','2020-01-22 18:53:39','6','<p>春节前回访客户，北京当代置业有限公司，北京葛洲坝集团，中建八局公司，中国装饰协会，河北旅投集团，河北兆祥房地产开发公司等各单位各公司，成本，招采，工程，各部门负责人及上级领导，表示节前看望，了解项目进展情况，为年后开展工作做好准备。</p>',NULL,'2000','否','3000','5',NULL,'a5d90cd4c02e4f3789b355b0006ed321','P4','客户回访，节前送礼.','飞机,动车或高铁','北京，石家庄',''),('2c9267606f9cace4016f9e739a420006','常青	','2020-01-13 18:29:33',NULL,NULL,'A04A17','2020-01-14 06:11:03','2020-01-16 18:11:29','3','<p>14号如约拜访复地集团北京城市公司倪董介绍蓝光集团煜明公司，为以后合作打基础。15号拜访招采部负责人，了解该公司通州项目情况，获取相关项目信息，为之后的投标工作做商务准备。</p>',NULL,'2500','否','2000','5',NULL,'a5d90cd4c02e4f3789b355b0006ed321','P4',NULL,'动车或高铁,飞机','北京市',''),('2c9267606f9cace4016fa2173d500007','郭炎宏','2020-01-14 11:27:09','guoyanhong','2020-01-14 11:32:19','A04A17','2020-01-07 11:24:20','2020-01-08 11:25:10','2','<p>去河南沟通漯河召陵区改造项目；许昌经济开发区市政配套项目。</p>','','￥3000.00','否','3000','4',NULL,'2703b6aa8fc344299f86a213e3262966','P4',NULL,'飞机,动车或高铁','郑州、许昌和洛阳',''),('2c9267606f9cace4016fa21b88eb0008','郭炎宏','2020-01-14 11:31:51',NULL,NULL,'A04A17','2020-01-13 11:28:14','2020-01-14 11:28:18','2','<p>去成都汇报项目</p>',NULL,'3200','否','50000','4',NULL,'2703b6aa8fc344299f86a213e3262966','P4',NULL,'飞机','成都',''),('2c9267606f9cace4016fa224e1fa0009','陈勇	','2020-01-14 11:42:03',NULL,NULL,'A04A17','2019-12-23 07:00:00','2019-12-25 12:00:00','2.5天','<p>赴成都集团总部汇报重点跟进项目情况并参加公司相关制度培训。</p>',NULL,'800元','否','1000','5',NULL,'0e76f48c7c2540508112126843779e7e','P3',NULL,'动车或高铁','2019年12月23日从重庆至成都；\n2019年12月25日从成都至重庆。',''),('2c9267606f9cace4016fa2790004000a','陈勇	','2020-01-14 13:13:56',NULL,NULL,'A04A17','2020-01-06 12:00:00','2020-01-06 20:00:00','0.5天','<p>陪同赵俊霖总、刘能君总、李舶连总赴重庆丰都县实地考察丰都县文化创意产业园一期建设项目现场。</p>','','500元','是','350公里','5',NULL,'0e76f48c7c2540508112126843779e7e','P3','自驾','其他','重庆丰都县',''),('2c9267606f9cace4016fac4e6fd0000f','孙六利','2020-01-16 11:03:39',NULL,NULL,'A04A17','2020-01-20 09:00:00','2020-01-22 18:00:00','3','<p>拜访济南客户，寻找可投标项目</p>','','约4000元','否','1800KM','4',NULL,'a5d90cd4c02e4f3789b355b0006ed321','P4','机票2394元，市内交通费约600元，招待费约1000元','飞机','济南','files/20200116110328192_济南出差拜访人员.xlsx'),('2c9267606fabfb63016fac01a69b0001','常青	','2020-01-16 09:39:46','changqing','2020-01-16 09:42:30','A04A17','2020-01-16 08:38:10','2020-01-20 18:38:16','4','<p>拜访复地集团上海城市公司招采部贺总，跟踪了解上海雅苑三期招标进展情况。</p>',NULL,'2400','否','1200','5',NULL,'a5d90cd4c02e4f3789b355b0006ed321','P4',NULL,'飞机,动车或高铁','上海',''),('2c9267606fb25362016fb2c2527e0001','吴家友','2020-01-17 17:07:57','wujiayou','2020-01-19 08:59:46','A04A17A15','2020-01-19 09:00:00','2020-01-19 18:00:00','1','<p>&nbsp; 到仁寿发展投资集团有限公司进行节前拜访！</p>',NULL,'900','是','180','4',NULL,'780b08b91e8a4241acf68a2d3080cbdb','P4','自驾车','其他',NULL,''),('2c9267606fb25362016fb2c253a70002','张伟1','2020-01-17 17:07:57','zhangwei','2020-01-17 18:07:33','A04A17','2020-01-19 14:00:01','2020-01-23 16:59:27','5',NULL,NULL,'5000','否','1000','5',NULL,'780b08b91e8a4241acf68a2d3080cbdb','P7',NULL,'飞机','山东济南，文登',''),('2c9267606fb25362016fc1723bb30006','常青	','2020-01-20 13:34:46',NULL,NULL,'A04A17','2020-01-20 08:51:41','2020-01-23 18:52:29','4','<p>拜访复地集团北京公司总负责人 常务副总 招采负责人为通州XO5地块住宅公寓项目做前期铺垫工作。</p>\n<p>拜访富力集团装饰部总负责人，节前礼节拜访为办理入库做准备工作。</p>\n<p>拜访富力地产集采部两位负责人，为进入地产公司全国项目做工作。</p>\n<p>节前拜访华远集团战采部两位负责人为办理入库工作做准备。</p>',NULL,'3000','否','1000','5',NULL,'a5d90cd4c02e4f3789b355b0006ed321','P4','19日晚结束上海出差坐动车到北京出差。20日-23日在北京开展节前客户拜访，商务招待工作工作。','动车或高铁,飞机','北京',''),('2c9267606fbc3346016fbc3346530000','孙六利','2020-01-19 13:07:54',NULL,NULL,'A04A17','2020-01-20 09:00:00','2020-01-22 18:00:00','3','<p>拜访济南客户，寻找可投标项目</p>','','约4000元','否','1800KM','5',NULL,'a5d90cd4c02e4f3789b355b0006ed321','P4','机票2394元，市内交通费约600元，招待费约1000元','飞机','济南','files/20200119010653913_dbfaddfcfc.jpg,files/20200119010743134_孙六利时间月日日工作计划表.xlsx'),('2c92676070665b420170a9072069003e','马利国','2020-03-05 12:49:41',NULL,NULL,'A04A17','2020-03-09 12:46:26','2020-03-17 12:47:23','9','<p>对接、洽谈西安区域项目，北京拜访项目居间人。</p>','','6500','否','1000','1',NULL,'2703b6aa8fc344299f86a213e3262966','P6',NULL,'飞机,火车','西安、北京',''),('2c92676070665b420170aef5ae5d004c','陈宝庆','2020-03-06 16:28:21',NULL,NULL,'A04A17','2020-03-02 08:30:38','2020-04-02 16:21:12','31','<p>赴云南协助邬存之总,推动楚雄州姚安县光禄古镇项目、大姚县2020年美丽县城建设项目及玉溪、红河州弥勒等重点项目。</p>',NULL,'15000','否','3000','2',NULL,'0e76f48c7c2540508112126843779e7e','M6',NULL,'飞机,动车或高铁','云南省昆明、楚雄、玉溪、红河等市州县',''),('2c92676070665b420170af35a196004d','赵强','2020-03-06 17:38:12',NULL,NULL,'A04A17','2020-03-09 09:00:00','2020-03-14 18:10:38','5','<p>到373工地去联系试培事宜，并对其他工种内容与项目部和工人沟通，准备续拍事务。</p>','','￥1000.00','是','11公里','1',NULL,'2703b6aa8fc344299f86a213e3262966','P3',NULL,'其他','373工地',''),('2c92676070665b420170bec7d0c10050','孙美超','2020-03-09 18:12:11',NULL,NULL,'A04A17','2020-03-10 08:00:59','2020-03-14 23:10:59','5天','<p>到三亚、深圳、广州沟通三亚市南繁科技城、中海地产等项目。</p>\n<p>&nbsp;</p>','杜乐庆','6500','否','5000','3',NULL,'2703b6aa8fc344299f86a213e3262966','P4','出差三亚为王大鹏、杜乐庆、孙美超一同前往。','飞机','三亚、深圳、广州',''),('2c92676070665b420170d1d4a73b0069','张义鹏','2020-03-13 10:58:59',NULL,NULL,'A04A17','2020-03-14 06:50:46','2020-03-20 22:51:44','7','<p>行程暂定：</p>\n<p>14号，济南西--绵阳，住绵阳，高铁。</p>\n<p>15号，绵阳、平武项目地考察及合作沟通（水发集团旅游项目）自驾</p>\n<p>16号，绵阳---成都，带客户到公司，并与赵总汇报，自驾</p>\n<p>17号--18号，开车20个小时，到达菏泽，参加菏泽项目座谈会，自驾</p>\n<p>19号，济宁市出差，对接绿化及任城区项目，自驾</p>\n<p>20号，济宁到济南，高铁。</p>',NULL,'5000','是','3500','2',NULL,'2703b6aa8fc344299f86a213e3262966','P4',NULL,'火车,动车或高铁','绵阳、成都、菏泽，济宁。',''),('2c92676070665b420170d1d6d2bb006a','李文道','2020-03-13 11:01:21','liwendao','2020-03-13 11:02:05','A04A17','2020-03-15 08:00:46','2020-03-20 19:00:00','6','<p>惠州铂汇公馆抢工支援。</p>',NULL,'6000','否','','5',NULL,'a5d90cd4c02e4f3789b355b0006ed321','M4',NULL,'飞机','惠州',''),('2c92676070665b420170d42309820071','张义鹏','2020-03-13 21:43:50',NULL,NULL,'A04A17','2020-03-14 06:41:28','2020-03-18 21:41:39','7','<p style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin: 0px 0px 1em; padding: 0px; color: rgba(0, 0, 0, 0.65); font-family: -apple-system, BlinkMacSystemFont, \