--
-- Table structure for table `bs_video_info`
--

DROP TABLE IF EXISTS `bs_video_info`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `bs_video_info` (
  `id` varchar(36) NOT NULL,
  `equip_name` varchar(100) DEFAULT NULL COMMENT '设备名称',
  `ip` varchar(100) DEFAULT NULL COMMENT 'IP',
  `port` varchar(100) DEFAULT NULL COMMENT '端口',
  `username` varchar(100) DEFAULT NULL COMMENT '用户名',
  `password` varchar(100) DEFAULT NULL COMMENT '明文密码',
  `org_res_name` varchar(100) DEFAULT NULL COMMENT '组织资源名称',
  `equip_no` varchar(100) DEFAULT NULL COMMENT '设备序列号',
  `code` varchar(100) DEFAULT NULL COMMENT '系统编码',
  `equip_type` varchar(100) DEFAULT NULL COMMENT '设备类型',
  `sim_channels` varchar(100) DEFAULT NULL COMMENT '模拟通道数',
  `dig_channels` varchar(100) DEFAULT NULL COMMENT '数字通道数',
  `alert_input` varchar(100) DEFAULT NULL COMMENT '报警输入数',
  `alert_output` varchar(100) DEFAULT NULL COMMENT '报警输出数',
  `intercom_channels` varchar(100) DEFAULT NULL COMMENT '对讲通道数',
  `intelligent` varchar(100) DEFAULT NULL COMMENT '智能',
  `intel_property` varchar(100) DEFAULT NULL COMMENT '专业智能属性',
  `origin_channels` varchar(100) DEFAULT NULL COMMENT '起始通道号',
  `surport` varchar(100) DEFAULT NULL COMMENT '附加支持',
  `setup_type` varchar(100) DEFAULT NULL COMMENT '鱼眼安装方式',
  `zone_name` varchar(100) DEFAULT NULL COMMENT '网域名称',
  `encode_password` varchar(128) DEFAULT NULL COMMENT '加密后密码',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `bs_video_info`
--

