INSERT INTO `onl_cgform_enhance_js` VALUES ('274b5d741a0262d3411958f0c465c5f0','genereate_person_config(row){\nconsole.log(\'选择\',row)\nalert(row.name + \'，个人积分配置生成成功！\');\n}','list',NULL,'e2faf977fdaf4b25a524f58c2441a51c'),('2cbaf25f1edb620bea2d8de07f8233a1','air_china_post_materiel_item_onlChange(){\n    return {\n        wl_name(){\n           \n            let id = event.row.id\n            let cnum = event.row.num\n            let value = event.value\n            let targrt = event.target\n            let columnKey = event.column.key\n           let nval = 200*cnum\n           console.log(\'row\',event.row);\n           console.log(\'cnum\',cnum);\n           let otherValues = {\'jifen\': nval}\n              \n                that.triggleChangeValues(targrt,id,otherValues)\n\n        }\n    }\n}','form',NULL,'e67d26b610dd414c884c4dbb24e71ce3'),('35d4ef464e5e8c87c9aa82ea89215fc1','','list',NULL,'e67d26b610dd414c884c4dbb24e71ce3'),('6ca2331fa2066db78c8701d56462c2e1','show(){\n  \n  debugger;\n  \n  this.$nextTick(() => {\n           \n    this.form.setFieldsValue({\"create_by\":\"age值\"})\n    \n  });\n}','form',NULL,'688a9ea8187d461e9e921fd5a5829201'),('6d9b61ba580f19297da563dffbaeca39','show(){\n   console.log(\'form\',that)\n   //this.form.setFieldsValue({\"name\":\"name值\"})  \n  that.$nextTick(() => {\n           //age是对应表的字段名\n            that.form.setFieldsValue({\"name\":\"age值\"})\n          });\n}','form',NULL,'113e4c22d62644598f9e2edc89423875');
