DROP TABLE IF EXISTS `pr_log_history`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `pr_log_history` (
  `id` varchar(36) NOT NULL COMMENT '主键',
  `table_name` varchar(100) DEFAULT NULL COMMENT '业务表名',
  `main_value` varchar(100) DEFAULT NULL COMMENT '表主键值',
  `proponents` varchar(100) DEFAULT NULL COMMENT '流程提案人',
  `business_data_id` varchar(100) DEFAULT NULL COMMENT '业务数据主键值',
  `business_code` varchar(100) DEFAULT NULL COMMENT '业务编号',
  `process_name` varchar(100) DEFAULT NULL COMMENT '流程名称',
  `employee` varchar(1000) DEFAULT NULL COMMENT '操作职员',
  `approve_user` varchar(100) DEFAULT NULL COMMENT '审批人员',
  `action` varchar(100) DEFAULT NULL COMMENT '操作动作',
  `action_opinion` text COMMENT '操作意见',
  `operate_time` datetime DEFAULT NULL COMMENT '操作时间',
  `functions_station` varchar(100) DEFAULT NULL COMMENT '职能岗位',
  `process_station` varchar(100) DEFAULT NULL COMMENT '流程岗位',
  `business_data` text COMMENT '业务数据',
  `content` text COMMENT '业务内容',
  `process_audit` varchar(100) DEFAULT NULL COMMENT '流程编码',
  `create_time` datetime DEFAULT NULL COMMENT '创建日期',
  `relate_data` text COMMENT '关联数据',
  `origin_data` text COMMENT '原始数据',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

