--
-- Table structure for table `pr_rights`
--

DROP TABLE IF EXISTS `pr_rights`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `pr_rights` (
  `id` varchar(36) NOT NULL COMMENT '主键',
  `create_by` varchar(50) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建日期',
  `update_by` varchar(50) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新日期',
  `sys_org_code` varchar(64) DEFAULT NULL COMMENT '所属部门',
  `business_module` varchar(100) DEFAULT NULL COMMENT '业务模块',
  `items` varchar(100) DEFAULT NULL COMMENT '关键事项',
  `unit` varchar(100) DEFAULT NULL COMMENT '发起单位',
  `no` varchar(100) DEFAULT NULL COMMENT '编号',
  `duty` varchar(100) DEFAULT NULL COMMENT '主责中心',
  `proposal` varchar(100) DEFAULT NULL COMMENT '提案',
  `audit` varchar(100) DEFAULT NULL COMMENT '审核',
  `approve` varchar(100) DEFAULT NULL COMMENT '审批',
  `participate` varchar(100) DEFAULT NULL COMMENT '参与',
  `notify` varchar(100) DEFAULT NULL COMMENT '备案/知会',
  `business_type` varchar(100) DEFAULT NULL COMMENT '业务类别',
  `sort` int(100) DEFAULT NULL COMMENT '排序',
  `conditions` varchar(1000) DEFAULT NULL COMMENT '条件',
  `addflag` varchar(100) DEFAULT '是' COMMENT '加签',
  `business` varchar(1000) DEFAULT NULL COMMENT '关联业务',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

