--
-- Table structure for table `pr_template`
--

DROP TABLE IF EXISTS `pr_template`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `pr_template` (
  `id` varchar(36) NOT NULL COMMENT '主键',
  `process_name` varchar(100) DEFAULT NULL COMMENT '模板名称',
  `no` varchar(32) DEFAULT NULL COMMENT '编号',
  `create_by` varchar(50) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建日期',
  `update_by` varchar(50) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新日期',
  `sys_org_code` varchar(64) DEFAULT NULL COMMENT '所属部门',
  `group_code` varchar(32) DEFAULT NULL COMMENT '组号',
  `group_name` varchar(32) DEFAULT NULL COMMENT '组名',
  `process_business_name` varchar(32) DEFAULT NULL COMMENT '流程业务名称',
  `functions` varchar(32) DEFAULT NULL COMMENT '职能名称',
  `functions_type` varchar(32) DEFAULT NULL COMMENT '职能类别',
  `operation` varchar(32) DEFAULT NULL COMMENT '操作',
  `downstream` varchar(32) DEFAULT NULL COMMENT '下游',
  `mode` varchar(32) DEFAULT NULL COMMENT '模式',
  `status` varchar(32) DEFAULT NULL COMMENT '状态',
  `type` varchar(32) DEFAULT NULL COMMENT '类型',
  `sort` int(32) DEFAULT NULL COMMENT '排序',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

